import {renderWorldMap,mountMap} from './map.js?v=0.3.0';
import {REGIONS,INVENTORY,NATIONS,NATION_ORDER,SCENARIOS,RESOURCES,UNITS,PHASES,ZONES,displayId,sideOf} from './data.js';
import {createGame,decision,dispatch,commandsAt,category,income,regionIncome,reduced,embattled,orderLimit,legalDestinations,movementPath,movementPlan,pinnedCount,spareTokens,hitTargets,bombingTargets,stanceStats,selectableHotspots,capacity,ports,productionCost,tradeAccess,portAdvantage,rank,canReorganize,convoyClusters} from './engine.js';
import {applyAI} from './ai.js';
import {HELP,guidance} from './help.js';
import {restore,autosave,saveSlot,readStore,loadSlot,parseImport,exportSave,download} from './storage.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let game=restore(),view='theater',selectedNation=game?Object.keys(game.nations).find(n=>game.nations[n].human)||game.turnOrder[0]:'uk',selectedRegion=game?NATIONS[selectedNation].capital:null,mapController=null,mapSnapshot=null,busy=false,paused=false,setupScenario='global',setupHumans=['uk'],undo=[],autoTimer=null,toastTimer;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const payload=d=>escape(JSON.stringify(d));
const button=(label,action,data={},cls='',disabled=false)=>`<button class="btn ${cls}" data-action="${action}" data-payload="${payload(data)}" ${disabled?'disabled':''}>${label}</button>`;
const help=key=>`<button type="button" class="help" data-help="${key}" aria-label="Help: ${escape(HELP[key]?.[0]||key)}" title="${escape(HELP[key]?.[0]||key)}"></button>`;
const title=(label,key)=>`<span class="section-title">${label}${help(key)}</span>`;
const zoneColors=['#e4e6e4','#79a5d9','#d9c567','#d9a36b','#e18084','#a4a7af'];
const colorOf=t=>({yellow:'#dcc468',blue:'#86b7e2',green:'#86c7a1',red:'#e58a81',black:'#111',white:'#f2f2e9'}[t]);
const paths={infantry:'M12 4a3 3 0 1 0 0 .1M9 9h6l3 6-2 1-2-4v7h-2v-5h-1v5H9v-7l-2 4-2-1z',artillery:'M3 16h18v3H3zM5 13h10l5-8 2 1-4 9H5zM7 18a2 2 0 1 0 0 .1m11-.1a2 2 0 1 0 0 .1',armor:'M3 13h18v6H3zM6 10h12v4H6zM11 5h7v2h-5v5h-2zM5 20h14v2H5z',fighter:'M11 2h2l1 8 8 6v2l-8-3v5l3 2v1l-5-1-5 1v-1l3-2v-5l-8 3v-2l8-6z',bomber:'M10 2h4l1 8 8 4v3l-8-1v4l3 1v2l-6-1-6 1v-2l3-1v-4l-8 1v-3l8-4z',submarine:'M3 14h17a4 4 0 0 1 0 7H5a4 4 0 0 1-2-7m6-5h5v7H9zM12 5h5v2h-3v4h-2z',cruiser:'M1 15h22l-4 6H6zM7 9h9v7H7zM9 4h2v7H9zM14 7h7v2h-7z',carrier:'M2 12h20l-3 9H5zM5 6h15v8H5zM7 8h11v2H7zM15 2h3v5h-3z',battleship:'M1 14h22l-4 7H5zM7 8h10v8H7zM10 2h3v7h-3zM3 10h6v2H3zM15 7h7v2h-7z'};
function unitIcon(t){return`<svg class="unit-icon" style="--unit:${colorOf(UNITS[t].color)}" aria-hidden="true" viewBox="0 0 24 26"><path d="${paths[t]}" fill="currentColor"/></svg>`;}
function unitChips(units){const counts={};for(const u of units)counts[u.type]=(counts[u.type]||0)+1;return`<div class="unitrow">${Object.entries(counts).map(([t,n])=>`<span class="unit-chip">${unitIcon(t)}${n} ${UNITS[t].name}</span>`).join('')}</div>`;}
const opt=(id,selected)=>`<option value="${id}" ${id===selected?'selected':''}>${displayId(id)} · ${escape(REGIONS[id].name)}</option>`;
function regionSelect(name,ids,selected=null){return`<select id="${name}" aria-label="${name.replaceAll('-',' ')}">${ids.map(id=>opt(id,selected)).join('')}</select>`;}
function nationName(n){return NATIONS[n]?.name||'Neutral';}
function panel(label,key,body,extra=''){return`<section class="panel ${extra}"><div class="panelhead"><h2>${title(label,key)}</h2></div><div class="panelbody">${body}</div></section>`;}
const tabs=[['theater','◎','World theater'],['orders','↗','Orders & commands'],['operations','⌁','Operations'],['intel','▥','National status'],['archive','◷','Save & reference']];
function nav(side=false){return`<nav class="${side?'side-nav':'bottomnav'}" aria-label="${side?'Main':'Mobile'} navigation">${tabs.filter(t=>side||t[0]!=='archive').map(([id,icon,label])=>`<button class="navitem ${view===id?'active':''}" data-action="view" data-payload="${payload({view:id})}" ${view===id?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('')}</nav>`;}
function chrome(body,welcome=false){return`<aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div>WAR ROOM<small>THE SITUATION ROOM</small></div></div><div class="eyebrow">Command center</div>${nav(true)}<div class="side-footer"><span class="tealtext">● LOCAL OPERATIONS</span><br>Solo AI · device saves<br>Second Edition / 2025<br><button class="help" data-help="fidelity" aria-label="Implementation status"></button> Unofficial playable alpha</div></aside><header class="topbar"><div class="brand"><img src="icon.svg" alt=""><div>WAR ROOM<small>THE SITUATION ROOM</small></div></div><div class="top-actions">${game?`<span class="ai-status">${busy?'AI thinking…':''}</span>${button('Save','view',{view:'archive'},'small')}${button('?','help',{key:'start'},'small')}`:button('How to play','help',{key:'start'},'small')}</div></header><main id="content" class="content">${body}</main>${welcome?'':nav()}`;}
function worldSVG(state=game,hero=false){return renderWorldMap(state,{selected:selectedRegion,hero});}
function welcome(){const scenario=SCENARIOS[setupScenario];return chrome(`<section class="hero"><div><div class="eyebrow">A global command. A fragile homeland.</div><h1>THE WORLD<br>IS YOUR<br><span style="color:var(--coral)">WAR ROOM.</span></h1><div class="subheading">THE SITUATION ROOM</div><p>Plan in secret. Coordinate your allies. Command the battle — and keep your nation together. A mobile-first adaptation of Larry Harris’s War Room.</p><div class="flex" style="margin-top:20px"><span class="pill">5 theaters</span><span class="pill">3 AI levels</span><span class="pill">Portable saves</span></div></div><div class="hero-world">${worldSVG(null,true)}<div class="stamp">GLOBAL OPERATIONS / 187 REGIONS</div></div></section><div class="setup-grid">${panel('Choose your theater','start',`<div class="scenario-options">${Object.entries(SCENARIOS).map(([id,s])=>`<label class="scenario-option"><input type="radio" name="scenario" value="${id}" ${id===setupScenario?'checked':''}><span><strong>${s.name}</strong><p>${s.description}</p></span></label>`).join('')}</div>`)}${panel('Take command','ai',`<p>Select the nations you will control. AI commands every other nation, including your allies. Select both alliances for local pass-and-play.</p><div class="setup-nations">${scenario.nations.map(n=>`<label class="check" style="--nation:${NATIONS[n].color}"><input type="checkbox" name="human" value="${n}" ${setupHumans.includes(n)?'checked':''}><span>${NATIONS[n].short}<small>${sideOf(n)==='allies'?'Allied Forces':'Axis'}</small></span></label>`).join('')}</div><div class="formgrid two"><label class="field"><span>AI difficulty ${help('ai')}</span><select id="difficulty"><option value="easy">Easy</option><option value="normal" selected>Normal</option><option value="hard">Hard</option></select></label><label class="field"><span>Seed (optional)</span><input id="seed" type="number" placeholder="Random"></label></div><details style="margin-top:14px"><summary class="muted" style="font-size:11px;cursor:pointer">Advanced official options</summary>${[['forceCap','Force Advantage batch cap'],['longRange','Long-range amphibious landings'],['bombRepair','Bomb damage repair'],['convoyCasualties','Take Her Down: convoy casualties'],['divedSubs','Take Her Down: submarine escape'],['limited','Six-round limited game']].map(([id,label])=>`<label class="check"><input type="checkbox" name="option" value="${id}"><span>${label}</span></label>`).join('')}</details><div class="actionrow">${button('Import saved game','import',{},'small')}${button('Begin operations →','newGame',{},'primary')}</div><p class="status-note">Original interface art. Unofficial playable alpha; remaining rules edge cases are documented. ${help('fidelity')} Standard full rules are the default; Quick Play and Quick Battle are not used.</p>`)} </div><div class="footer-links"><a href="https://nightingale-games.com/war-room" target="_blank" rel="noopener">Official game</a><a href="docs/SOURCES.md" target="_blank">Sources & implementation notes</a><a href="https://github.com/Nathan-Culver/war-room" target="_blank" rel="noopener">GitHub</a></div>`,true);}
function nationalResources(n){const p=game.nations[n],inc=income(game,n);return`<div class="resources">${RESOURCES.map(k=>`<div class="resource"><div class="resname">${k==='osr'?'Other strategic':k}${help('economy')}</div><div class="value ${k}">${p.resources[k]}</div><div class="income">+${inc[k]} / round ${k==='osr'?'OSR':''}</div></div>`).join('')}</div>`;}
function header(){const d=decision(game),g=guidance(game,d),p=game.nations[selectedNation];return`<div class="pagehead"><div><div class="eyebrow">${SCENARIOS[game.scenario].name} / ${game.winner?'War concluded':'Situation report'}</div><h1>${tabs.find(x=>x[0]===view)?.[2]||'Command center'}</h1><p>${NATIONS[selectedNation].name} · ${p.human?'Your command':game.difficulty+' AI'} · ${game.rules}</p></div><div class="round-tag">ROUND <b>${String(game.round).padStart(2,'0')}</b><br><small>${game.winner?'FINAL':PHASES[game.phase]}</small></div></div><div class="phase-track" aria-label="Round phases">${PHASES.slice(1).map((ph,i)=>`<span class="phase ${game.phase===i+1?'active':''}" ${game.phase===i+1?'aria-current="step"':''}><i>${i+1}</i>${ph}</span>`).join('')}</div><div class="players">${Object.entries(game.nations).map(([n,q])=>`<button class="playerchip ${n===selectedNation?'current':''}" style="--nation:${NATIONS[n].color}" data-action="nation" data-payload="${payload({nation:n})}"><span class="avatar">${NATIONS[n].prefix.toUpperCase()}</span><span><span class="name">${NATIONS[n].short}</span><span class="sub" style="display:block">${q.collapsed?'Collapsed':ZONES[q.zone]+' · '+q.stress+' stress'} · ${q.human?'You':'AI'}</span></span></button>`).join('')}</div>${nationalResources(selectedNation)}<section class="guidance"><div class="copy"><div class="eyebrow">${busy?'AI operations in progress':'What to do next'}</div><h2>${escape(g[0])}</h2><p>${escape(g[1])}</p></div><div class="controls">${help(g[2])}${button(busy?'Pause AI':'Go to decision →',busy?'pause':'view',busy?{}:{view:game.phase===2&&game.step==='planning'?'orders':'operations'},'teal small')}</div></section>`;}
function commandCard(c,withActions=true){const own=game.nations[c.nation].human;return`<article class="command" style="--nation:${NATIONS[c.nation].color}"><div class="between"><div><div class="command-name">${c.carrierFighter?'Carrier fighter':c.neutral?'Neutral defense':category(c).toUpperCase()+' '+c.number} <span class="badge-num">${c.units.length}/8</span></div><div class="sub">${NATIONS[c.nation].short} · ${displayId(c.region)} ${escape(REGIONS[c.region].name)}${c.airTag?' · Must land':''}</div></div>${withActions&&own&&!c.carrierFighter&&!c.neutral?button('Manage','manage',{command:c.id},'small'):''}</div>${unitChips(c.units)}</article>`;}
function mapPanel(){
 const valid=game.regions[selectedRegion],selected=valid?REGIONS[selectedRegion]:null;
 const control=(id,label,text,extra='')=>`<button class="btn small" data-map-control="${id}" aria-label="${label}" title="${label}" ${extra}>${text}</button>`;
 return`<section class="panel map-panel"><div class="panelhead"><h2>${title('World theater','map')}</h2><span class="tag">${Object.keys(game.regions).length} regions</span></div>
 <div class="map-toolbar"><div class="map-find"><select id="find-region" aria-label="Find region"><option value="">Find a region…</option>${Object.keys(game.regions).sort((a,b)=>REGIONS[a].name.localeCompare(REGIONS[b].name)).map(id=>opt(id)).join('')}</select>${help('mapFind')}</div>
 <div class="map-controls" role="group" aria-label="Map controls"><span class="map-control-group">${control('out','Zoom out','−')}${control('fit','Fit whole map','100%','data-map-zoom')}${control('in','Zoom in','+')}${help('mapZoom')}</span><span class="map-control-group">${control('left','Rotate map counterclockwise','↶')}${control('right','Rotate map clockwise','↷')}${help('mapRotate')}</span><span class="map-control-group">${control('expand','Open full screen map','Full screen','aria-expanded="false"')}${help('mapFullScreen')}</span><span class="map-control-group">${control('labels','Toggle crisp detail labels','Labels on','aria-pressed="true"')}${help('mapQuality')}</span></div></div>
 <div class="map-viewport" id="map-viewport" tabindex="0" role="region" aria-label="Interactive War Room map: drag to pan, pinch to zoom, tap a region" aria-describedby="map-gesture-hint"><div class="map-stage">${worldSVG()}</div></div>
 <div class="map-selection" data-map-selection><div><span class="eyebrow">Selected region</span><strong>${selected?displayId(selectedRegion)+' · '+escape(selected.name):'Tap a region to inspect'}</strong></div>${selected?button('Details','mapDetails',{},'small'):''}${help('mapInspect')}</div>
 <div class="map-hint" id="map-gesture-hint"><span>Drag to pan · Pinch or double tap to zoom</span>${help('mapTouch')}<span class="map-status" data-map-status>100% zoom</span></div>
 <div class="legend"><span><i style="background:var(--coral)"></i>Active hotspot</span><span><i style="background:var(--gold)"></i>Selected</span><span>Nation letters = new controller</span><span>Numbers = units</span>${game.scenario!=='global'?'<span>Dimmed = outside theater</span>':''}${help('mapSymbols')}</div></section>`;
}
function attachMap(){const viewport=document.querySelector('#map-viewport');if(!viewport)return;mapController=mountMap(viewport,{snapshot:mapSnapshot,onChange:s=>{mapSnapshot=s;},onSelect:id=>handle('region',{region:id})});}
function regionPanel(){if(!selectedRegion||!game.regions[selectedRegion])selectedRegion=Object.keys(game.regions).find(id=>game.regions[id].owner===selectedNation)||Object.keys(game.regions)[0];const id=selectedRegion,r=REGIONS[id],q=game.regions[id],res=regionIncome(game,id);const connections=r.adjacent.filter(l=>game.regions[l.match(/^[a-z]\d+/)[0]]);return panel('Region intelligence','map',`<article class="region-card"><div class="code">${displayId(id)} ${SCENARIOS[game.scenario].capitals.includes(id)?' / CAPITAL':''}</div><h2>${escape(r.name)}</h2><p style="font-size:11px;margin-top:5px">${r.sea?'International waters':nationName(q.owner)+' control'}${embattled(game,id)?' · <span class="red">Embattled</span>':''}</p><div class="stats"><div class="statbox"><b>${r.sv||'—'}</b><small>Strategic value</small></div><div class="statbox"><b>${r.industry?capacity(game,id):'—'}</b><small>Industry capacity</small></div><div class="statbox"><b>${q.bombs||0}</b><small>Bomb damage</small></div></div>${!r.sea?`<div class="flex" style="font-size:11px">${RESOURCES.map(k=>`<span class="${k}">${res[k]||0} ${k.toUpperCase()}</span>`).join(' · ')}${reduced(game,id)?'<span class="tag">Reduced card</span>':''}</div>`:''}${r.sea&&(r.convoys||[]).length?`<div class="spacer"></div><h3>Convoys ${help('convoy')}</h3>${convoyClusters(game,id).map(cl=>`<p style="font-size:10px;margin-top:6px">Cluster ${cl.id+1}: ${cl.ships.map(sh=>sh.count+' '+sh.resource.toUpperCase()+' / '+NATIONS[sh.owner].short).join(' · ')}</p>`).join('')}${button('Shared Axis convoy liability','convoyLiability',{region:id},'small')}`:''}${r.trade?`<p style="font-size:11px;margin-top:10px">Neutral trade: ${r.trade.toUpperCase()} ${help('trade')}</p>`:''}${r.mobilization?`<p style="font-size:11px;margin-top:10px">Chinese mobilization: ${r.sv||r.mobilization} ${help('china')}</p>`:''}${Object.keys(r.canals||{}).length?`<div class="infobox" style="margin-top:10px">Narrow passages: ${Object.entries(r.canals).map(([to,req])=>displayId(to)+' requires '+req.map(x=>REGIONS[x].name).join(' + ')).join('; ')}</div>`:''}<div style="margin-top:15px"><div class="eyebrow">Connections / # rail / ⚓ port / × impassable</div><div class="connection-list">${connections.map(link=>{const id=link.match(/^[a-z]\d+/)[0];return button(displayId(id)+(link.endsWith('#')?' #':link.endsWith('$')?' ⚓':link.endsWith('^')?' ×':''),'region',{region:id},'small');}).join('')}</div></div>${commandsAt(game,id).length?commandsAt(game,id).map(c=>commandCard(c)).join(''):'<div class="empty" style="margin-top:15px">No commands in this region.</div>'}${q.construction.length?`<div class="spacer"></div><h3>Under construction ${help('production')}</h3>${unitChips(q.construction)}`:''}</article>`);}
function ordersPanel(){const n=selectedNation,p=game.nations[n],open=game.phase===2&&game.step==='planning'&&p.human&&!p.sealed;const cs=game.commands.filter(c=>c.nation===n&&!c.carrierFighter&&!c.neutral);return panel('Secret orders / '+NATIONS[n].short,'orders',`${open?`<p>Your destination is binding once sealed. Destinations are validated again during movement, when enemy actions can block a route.</p><div class="formgrid two"><label class="field"><span>Command</span><select id="order-command">${cs.map(c=>`<option value="${c.id}">${category(c).toUpperCase()} ${c.number} · ${displayId(c.region)} · ${c.units.length} units</option>`).join('')}</select></label><label class="field"><span>Destination</span>${regionSelect('order-destination',Object.keys(game.regions),cs[0]?.region)}</label></div><div id="order-route-note" class="status-note"></div>${button('Add / replace order','addOrder',{},'teal full')}`:p.human?`<div class="infobox">${p.sealed&&game.phase===2?'These orders are sealed. Wait for all nations to commit.':'Orders are written during Strategic Planning. You can review your sheet here.'}</div>`:'<div class="infobox">AI orders stay secret until their movement turn. Public resources and positions remain visible.</div>'}${p.human?`<div class="spacer"></div>${p.orders.length?p.orders.map((o,i)=>{const c=game.commands.find(x=>x.id===o.command);return`<div class="orderrow"><span class="badge-num">${i+1}</span><div>${c?category(c).toUpperCase()+' '+c.number:o.command} → ${displayId(o.to)}<p>${escape(REGIONS[o.to].name)}</p></div>${open?button('×','removeOrder',{index:i},'small'):''}</div>`;}).join(''):'<div class="empty">No orders written. Holding all commands is legal.</div>'}<div class="spacer"></div><div class="formgrid two"><label class="field"><span>Oil bid ${help('bid')}</span><input id="oil-bid" type="number" min="0" max="${p.resources.oil}" value="${p.bid}" ${open&&n!=='china'?'':'disabled'}></label><div class="field"><span>Orders available</span><div class="statbox"><b>${p.orders.length} / ${orderLimit(game,n)}</b></div></div></div>${open?`<div class="actionrow">${button('Seal orders & oil bid →','sealOrders',{nation:n},'primary')}</div>`:''}`:''}`);}
function dieRow(dice,current=false){return`<div class="dice">${dice.map((c,i)=>`<span class="die ${c} ${current&&i===0?'current':''}" style="--die:${colorOf(c)}" title="${c}">${c==='black'?'★':c==='white'?'◇':c[0].toUpperCase()}</span>`).join('')}</div>`;}
function chooseButtons(es,action,extra={}){return`<div class="choices">${es.map(e=>button(unitIcon(e.type)+`${UNITS[e.type].name} · ${NATIONS[e.nation]?.short||''}${e.stance?' · '+e.stance:''}${e.hits?' · '+e.hits+' hits':''}`,action,{...extra,uid:e.uid})).join('')}</div>`;}
function battleBoard(){const b=game.battle;if(!b)return'';return`<div class="spacer"></div><div class="between"><h3>${REGIONS[b.id].name}</h3><span class="tag">${b.mode.toUpperCase()} / ${b.stage.toUpperCase()}</span></div>${b.lastDice?.length?dieRow(b.lastDice):''}${b.colors?.length?`<p class="muted" style="font-size:10px">Unassigned results</p>${dieRow(b.colors,true)}`:''}<div class="battle-grid">${['axis','allies'].map(side=>`<div class="battle-side"><h3>${side==='axis'?'Axis':'Allied Forces'} <span class="muted">${NATIONS[b.commanders[side]]?.short||''}</span></h3>${b.entries.filter(e=>e.side===side).map(e=>{const stats=stanceStats(e,b.mode);return`<div class="stance-row ${e.dead?'dead':''}">${unitIcon(e.type)}<div class="unit-info">${UNITS[e.type].name}<small>${NATIONS[e.nation].short} · ${stats[0]} / ${stats[1]} / ${stats[2]} HP${e.hits?' · '+e.hits+' hits':''}${e.dead?' · LOST':e.escaped?' · DIVED':''}</small></div>${b.stage==='stances'&&b.stanceSide===side&&game.nations[b.commanders[side]]?.human?`<select data-stance="${e.uid}" aria-label="Stance for ${e.uid}">${Object.keys(UNITS[e.type][b.mode]||{}).map(k=>`<option value="${k}" ${k===e.stance?'selected':''}>${k}</option>`).join('')}</select>`:`<span class="tag">${e.stance||'Transport'}</span>`}</div>`;}).join('')||'<p style="font-size:11px">No units</p>'}${b.totals?`<p style="font-size:11px;margin-top:10px">${b.totals[side]} dice in this stage${b.types?.[side]>b.types?.[side==='axis'?'allies':'axis']?' · Force Advantage':''}</p>`:''}${b.mode==='sea'&&portAdvantage(game,b.id,side)?'<span class="pill">Port Advantage</span>':''}</div>`).join('')}</div>${b.log.length?`<div class="battle-log">${b.log.slice(0,5).map(escape).join('<br>')}</div>`:''}`;}
function operations(){const d=decision(game),n=d.nation,p=game.nations[n],b=game.battle;let out='';if(n&&!p?.human){out=`<p>${NATIONS[n].short} is resolving ${d.kind}. The AI follows the same rules and resource costs.</p>${button(paused?'Resume AI →':'Run AI →','resume',{},'primary full')}`;return panel('Current operation','combat',out+battleBoard());}
switch(d.kind){
case'income':out=`<div class="table-scroll"><table class="ledger"><thead><tr><th>Nation</th><th>Oil</th><th>Iron</th><th>OSR</th></tr></thead><tbody>${Object.keys(game.nations).filter(n=>!game.nations[n].collapsed).map(n=>`<tr><td>${NATIONS[n].short}</td>${RESOURCES.map(k=>`<td class="${k}">+${income(game,n)[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="actionrow">${button('Collect all national income →','dispatch',{type:'income'},'primary')}</div>`;break;
case'planning':out=`<p>Choose your nation above, write orders, set an oil bid and seal your sheet. Orders and purchases are never shared between allied nations.</p>${button('Write orders →','view',{view:'orders'},'primary full')}`;break;
case'rank':out=`<p>Paid bids: ${Object.keys(game.nations).map(n=>NATIONS[n].short+' '+game.nations[n].bid).join(' · ')}</p><div class="choices">${Array.from({length:game.turnOrder.filter(n=>!game.nations[n].collapsed).length},(_,slot)=>button(`Rank ${slot+1}${game.chosenRanks[slot]?' · '+NATIONS[game.chosenRanks[slot]].short:''}`,'dispatch',{type:'rank',slot},game.chosenRanks[slot]?'':'teal',!!game.chosenRanks[slot])).join('')}</div>`;break;
case'move':{const o=d.order,c=game.commands.find(x=>x.id===o.command),plan=c?movementPlan(game,c,o.to):{},pin=plan.pin||0,path=plan.path||null;out=`<p>Order ${o.row+1}: ${c?category(c).toUpperCase()+' '+c.number:o.command} → <strong>${displayId(o.to)} ${REGIONS[o.to].name}</strong></p>${c?commandCard(c,false):''}<div class="infobox" style="margin-top:12px">${path?'Route: '+path.map(displayId).join(' → '):'The route is blocked or no longer legal. This order must be canceled.'}${pin?' · '+pin+' of '+c.units.length+' units pinned in '+displayId(plan.pinRegion)+'.':''}</div>${c&&['air','naval'].includes(category(c))||c&&category(c)==='land'&&REGIONS[c.region].sea?`<label class="field" style="margin-top:12px"><span>Route (optional intermediate region / loop)</span><select id="movement-via"><option value="">Automatic route / hold</option>${REGIONS[c.region].adjacent.map(l=>l.match(/^[a-z]\d+/)[0]).filter(id=>game.regions[id]&&REGIONS[id].adjacent.some(l=>l.match(/^[a-z]\d+/)[0]===o.to)&&movementPath(game,c,o.to,{via:id})).map(id=>opt(id)).join('')}</select></label>`:''}<div id="pin-selection">${pin>0&&pin<c.units.length?`<p style="font-size:11px;margin-top:12px">Choose exactly ${pin} units to leave behind:</p>${c.units.map(u=>`<label class="check"><input type="checkbox" name="leave" value="${u.uid}"><span>${UNITS[u.type].name} ${u.uid}</span></label>`).join('')}`:''}</div><div class="actionrow">${button('Cancel order','dispatch',{type:'move',cancel:true},'small')}${button('Execute written order →','executeMove',{},'primary')}</div>`;break;}
case'launch':out=`<p>Carrier at ${displayId(d.region)}. Choose a launch destination, or keep its fighter in storage.</p>${regionSelect('launch-destination',[d.region,...REGIONS[d.region].adjacent.map(l=>l.match(/^[a-z]\d+/)[0])].filter(id=>game.regions[id]))}<div class="actionrow">${button('Do not launch','dispatch',{type:'launch',to:null},'small')}${button('Launch fighter','launchFighter',{},'primary')}</div>`;break;
case'hotspot':out=`<p>${Object.keys(game.hotspots).length} active hotspots remain. ${NATIONS[n].short} selects next.</p><div class="choices">${selectableHotspots(game,n).map(id=>button(`${displayId(id)} · ${REGIONS[id].name}<span class="tag">${game.hotspots[id]}</span>`,'dispatch',{type:'hotspot',region:id},'teal')).join('')}</div>`;break;
case'stances':out=`<p>${NATIONS[n].name} commands this alliance. Change individual stances on the battle board below, then commit. Air / Surface / HP values are shown.</p>${b.participants[d.side].length>1?`<label class="field"><span>Alliance commander</span><select id="battle-commander">${b.participants[d.side].map(who=>`<option value="${who}" ${who===n?'selected':''}>${NATIONS[who].short}</option>`).join('')}</select></label>`:''}${button('Commit '+d.side+' stances →','dispatch',{type:'stancesReady'},'primary full')}`;break;
case'roll':out=`<p>${NATIONS[n].short}: roll ${b.batches[0].count} dice in the ${b.stage} stage. ${help('dice')}</p>${button('Roll '+b.batches[0].count+' dice →','dispatch',{type:'roll'},'primary full')}`;break;
case'hit':{const ts=hitTargets(game);out=`<p>Assign the <strong style="color:${colorOf(b.colors[0])}">${b.colors[0].toUpperCase()}</strong> result. ${help('damage')}</p>${ts.length?chooseButtons(ts,'dispatch',{type:'hit'}):'<div class="infobox">This result has no legal target and misses.</div>'}${!ts.length||b.colors[0]==='black'?button('Record miss →','dispatch',{type:'hit',uid:null},'full small'):''}`;break;}
case'escort':out=`<p>A hit targets a carrier or battleship. An escort cruiser may absorb it instead.</p>${chooseButtons(b.entries.filter(e=>d.escorts.includes(e.uid)),'dispatch',{type:'escort'})}${button('Let the original target take the hit','dispatch',{type:'escort',uid:null},'full small')}`;break;
case'garrison':out=`<p>The territory has no defending units. Its garrison rolls two dice; a matching pair eliminates one invading land unit.</p>${button('Roll garrison defense →','dispatch',{type:'garrisonRoll'},'primary full')}`;break;
case'garrisonHit':out=`<p>The garrison scored a matching pair. Choose the lost invader.</p>${chooseButtons(b.garrisonTargets,'dispatch',{type:'garrisonHit'})}`;break;
case'bombRoll':out=`<p>Resolve this strategic bomber’s four dice separately.</p>${button('Roll bombing raid →','dispatch',{type:'bombRoll'},'primary full')}`;break;
case'bombHit':{const ts=bombingTargets(game);out=`<p>Apply the ${b.colors[0].toUpperCase()} bombing result.</p><div class="choices">${ts.map(t=>button(t.label,'dispatch',{type:'bombHit',target:t.key})).join('')}</div>${!ts.length||b.colors[0]==='black'?button('No damage','dispatch',{type:'bombHit',target:null},'full small'):''}`;break;}
case'repair':out=`<p>Repair a damaged ${UNITS[d.unit.type].name} belonging to ${NATIONS[n].short}.</p>${d.free?button('Free port repair →','dispatch',{type:'repair'},'primary full'):`<div class="choices">${RESOURCES.filter(k=>p.resources[k]>0).map(k=>button('Pay 1 '+k.toUpperCase()+' ('+p.resources[k]+' available)','dispatch',{type:'repair',resource:k})).join('')}</div>${button('Decline repair · eliminate unit','dispatch',{type:'repair'},'danger full')}`}`;break;
case'capture':{const count=REGIONS[b.id].original==='neutral'?0:SCENARIOS[game.scenario].capitals.includes(b.id)?3:1;out=`<label class="field"><span>Territory controller (liberation rules apply)</span><select id="capture-owner">${b.captureCandidates.map(n=>`<option value="${n}">${NATIONS[n].name}</option>`).join('')}</select></label><p style="font-size:11px;margin-top:14px">Distribute ${count} medals among participants:</p>${b.participants[sideOf(b.captureCandidates[0])].map((n,i)=>`<label class="field"><span>${NATIONS[n].short}</span><input data-medals="${n}" type="number" min="0" max="${count}" value="${i===0?count:0}"></label>`).join('')}<div class="actionrow">${button('Confirm control & medals →','capture',{},'primary')}</div>`;break;}
case'subEscape':out=`<p>This submarine escaped the batch by diving. It may remain here or move into one adjacent sea with a spare command token.</p>${regionSelect('sub-destination',[b.id,...REGIONS[b.id].adjacent.map(l=>l.match(/^[a-z]\d+/)[0]).filter(id=>game.regions[id]&&REGIONS[id].sea)])}<div class="actionrow">${button('Confirm escape','subEscape',{},'primary')}</div>`;break;
case'convoyAssign':out=`<p>Assign command ${d.command.number||'carrier fighter'} (${d.command.units.length} units) to one convoy cluster.</p><div class="choices">${b.convoys.map(cl=>button('Convoy '+(cl.id+1)+' · '+cl.ships.map(x=>x.count+' '+x.resource+' / '+NATIONS[x.owner].short).join(', '),'dispatch',{type:'convoyAssign',cluster:cl.id})).join('')}</div>`;break;
case'convoyRoll':out=button('Roll convoy raid →','dispatch',{type:'convoyRoll'},'primary full');break;
case'convoyWild':out=`<p>Choose the black die’s resource target.</p><div class="choices">${RESOURCES.map(k=>button(k.toUpperCase(),'dispatch',{type:'convoyWild',resource:k})).join('')}</div>`;break;
case'landing':{const ids=legalDestinations(game,d.command,true);out=commandCard(d.command,false)+`<div class="spacer"></div>${ids.length?`<label class="field"><span>Friendly landing territory</span>${regionSelect('landing-destination',ids)}</label><div class="actionrow">${button('Land air command →','landAir',{},'primary')}</div>`:`<div class="infobox">No legal landing exists. This air command is lost.</div>${button('Record lost aircraft','dispatch',{type:'land',to:null},'danger full')}`}`;break;}
case'deployLoss':out=`<p>Bombing reduced ${REGIONS[d.region].name}’s capacity to ${capacity(game,d.region)}. Select an excess unit to remove.</p>${chooseButtons(game.regions[d.region].construction,'dispatch',{type:'deployLoss'})}`;break;
case'deploy':{const u=d.unit,ids=UNITS[u.type].category==='naval'?ports(u.region).filter(id=>game.regions[id]):[u.region];out=`<p>${UNITS[u.type].name}, built in ${REGIONS[u.region].name}. It will merge into a compatible command with room, or use a spare token.</p>${regionSelect('deploy-destination',ids)}<div class="actionrow">${button('Deploy / defer if no token →','deployUnit',{},'primary')}</div>`;break;}
case'reorganize':out=`<p>All aircraft and construction have been processed. Use Orders & commands to reorganize your stacks, then proceed to morale.</p><div class="actionrow">${button('Manage commands','view',{view:'orders'},'small')}${button('Begin national morale →','dispatch',{type:'refitDone'},'primary')}</div>`;break;
case'cancelStress':{const max=Math.min(p.medals+p.goods,p.stress);out=`<p>${p.lastCasualtyPoints} casualty points added ${p.lastCasualtyStress} stress. Current total: <b>${p.stress}</b>.</p><p>${p.medals} medals + ${p.goods} civilian goods available.</p><label class="field"><span>Spend to cancel stress (0–${max})</span><input id="morale-count" type="number" min="0" max="${max}" value="${max}"></label><div class="actionrow">${button('Confirm stress reduction →','moraleSpend',{},'primary')}</div>`;break;}
case'recover':{const th=SCENARIOS[game.scenario].thresholds[n];out=`<p>Homeland: ${ZONES[p.zone]}. Remaining stress: ${p.stress}. Available medals and goods: ${p.medals+p.goods}.</p><div class="choices">${p.zone>0&&p.medals+p.goods>=th?button('Spend '+th+' · improve one zone','dispatch',{type:'morale',count:th},'teal'):''}${button('Retain medals and continue →','dispatch',{type:'morale',count:0},'primary')}</div>`;break;}
case'penalty':out=d.pay?`<p>Recurring homeland penalty: pay ${d.pay} more resources.</p><div class="choices">${RESOURCES.filter(k=>p.resources[k]>0).map(k=>button('Pay 1 '+k.toUpperCase()+' · '+p.resources[k]+' available','dispatch',{type:'penaltyPay',resource:k})).join('')}</div>`:`<p>Gray-zone desertion: choose ${d.desert} more units to remove.</p>${chooseButtons(game.commands.filter(c=>c.nation===n).flatMap(c=>c.units.map(u=>({...u,nation:n}))),'dispatch',{type:'desert'})}`;break;
case'production':return productionPanel(n);
case'finished':out=`<h2>${game.winner==='draw'?'The war ends in a draw.':game.winner.toUpperCase()+' wins the war.'}</h2><p style="margin-top:10px">Victory checked against ${SCENARIOS[game.scenario].name} conditions. The final state and full log remain available.</p><div class="actionrow">${button('Export final save','export',{},'teal')}${button('New scenario','newSetup',{},'primary')}</div>`;break;
}
return panel('Current operation','combat',`<div class="decision-title"><span class="eyebrow">${d.nation?NATIONS[d.nation].name:PHASES[game.phase]||'Final report'}</span>${help(guidance(game,d)[2])}</div>${out}${battleBoard()}`);}
function productionPanel(n){const p=game.nations[n],factories=Object.keys(game.regions).filter(id=>game.regions[id].owner===n&&(REGIONS[id].industry||n==='china'&&REGIONS[id].mobilization)),cost=productionCost(p.plan),editable=p.human&&!p.sealed;return panel('Production / '+NATIONS[n].short,'production',`<p>Purchase in secret. Normal construction deploys during next round’s Refit. Chinese infantry mobilizes immediately.</p>${editable?`<label class="field"><span>Factory / mobilization territory</span>${regionSelect('production-factory',factories)}</label><div class="production-list">${Object.keys(UNITS).filter(t=>n!=='china'||['infantry','artillery'].includes(t)).map(t=>`<button class="purchase" data-action="buy" data-payload="${payload({type:t,nation:n})}">${unitIcon(t)}<span><span class="name">${UNITS[t].name}</span><span class="cost" style="display:block">${UNITS[t].cost.map((v,i)=>v?`${v} ${RESOURCES[i].toUpperCase()}`:'').filter(Boolean).join(' · ')}</span></span></button>`).join('')}</div><div class="spacer"></div>${button('Civilian goods · any 5 resources','goods',{nation:n},'teal full')}`:''}<div class="spacer"></div>${p.plan.length?p.plan.map((u,i)=>`<div class="orderrow"><span>${u.type==='goods'?'◇':UNITS[u.type].symbol}</span><div>${u.type==='goods'?'Civilian goods':UNITS[u.type].name+' · '+REGIONS[u.region].name}<p>${u.type==='goods'?RESOURCES.map(k=>u.payment[k]+' '+k).join(' · '):'Capacity '+capacity(game,u.region)}</p></div>${editable?button('×','removePurchase',{nation:n,index:i},'small'):''}</div>`).join(''):'<div class="empty">No purchases queued. Saving resources is legal.</div>'}<div class="infobox" style="margin-top:12px">Reserved: ${RESOURCES.map(k=>cost[k]+' '+k.toUpperCase()).join(' · ')}<br>Remaining: ${RESOURCES.map(k=>(p.resources[k]-cost[k])+' '+k.toUpperCase()).join(' · ')}</div>${editable?`<div class="actionrow">${button('Trade / repair','tradeMenu',{nation:n},'small')}${button('Seal production →','dispatch',{type:'productionSeal',nation:n},'primary')}</div>`:''}`);}
function nationalPanel(n){const p=game.nations[n],th=SCENARIOS[game.scenario].thresholds[n];return panel(NATIONS[n].name,'morale',`<div class="zone-track">${ZONES.map((z,i)=>`<span class="${p.zone===i?'active':''}" style="--zone:${zoneColors[i]}">${z}</span>`).join('')}</div><div class="stats"><div class="statbox"><b>${p.stress}/${th}</b><small>Stress / threshold</small></div><div class="statbox"><b>${p.medals+p.goods}</b><small>Medals + goods</small></div><div class="statbox"><b>${Object.values(game.regions).filter(r=>r.owner===n).length}</b><small>Territories</small></div></div><p>Orders: ${orderLimit(game,n)} · Commands: ${game.commands.filter(c=>c.nation===n).length}/${INVENTORY[n].length} · ${p.collapsed?'Collapsed':ZONES[p.zone]+' homeland'}</p><div class="spacer"></div><div class="infobox">${p.zone===0?'Your nation is stable. Preserve resources and plan your next offensive.':p.zone>=4?'No new resources. Reduce stress and buy civilian goods when possible.':p.zone>=2?'Your rail network, Port Advantage and sea trade are unavailable.':'Pay three resources during Morale each round.'} ${help('zones')}</div><div class="spacer"></div><h3>Casualties awaiting conversion</h3>${Object.entries(p.casualties).length?unitChips(Object.entries(p.casualties).filter(([t])=>UNITS[t]).flatMap(([t,k])=>Array(k).fill({type:t}))):'<p style="font-size:11px;margin-top:10px">None recorded.</p>'}${p.casualties.convoy?`<p>${p.casualties.convoy} convoy losses × 6 points</p>`:''}<div class="spacer"></div><h3>Command token availability ${help('commands')}</h3><div class="flex" style="margin-top:10px">${['land','air','naval'].map(cat=>`<span class="tag">${cat.toUpperCase()} · ${spareTokens(game,n,cat).length} spare</span>`).join('')}</div>`);}
function diplomacyPanel(){return panel('Diplomacy & victory','diplomacy',`<div class="stack"><div class="infobox">${game.scenario==='global'?'Axis: hold any two of Eastern United States, Great Britain and Moscow. Allies: hold both Greater Germany and Japan.':game.scenario==='europe'?'Axis: hold one of Great Britain, Moscow or Eastern United States. Allies: hold Greater Germany.':game.scenario==='pacific'?'Japan: hold Eastern Australia or India, plus Hawaii, Alaska or Western United States. Allies: hold Japan.':game.scenario==='nafrica'?'Axis: hold Egypt and Middle East, or Great Britain, or Eastern United States. Allies: hold Italy, or all five North African territories.':'Control both Moscow and Greater Germany at the end of Morale, or force the enemy nation to collapse.'}</div>${[['japan','Soviet–Japanese pact'],['sino','Sino-Soviet restrictions'],['stalin','Stalin Doctrine']].map(([id,label])=>`<div class="between"><span style="font-size:11px">${label}</span><span class="tag">${game.pacts[id]?'ACTIVE':'INACTIVE'}</span></div>`).join('')}${game.pacts.japan&&['ussr','japan'].includes(selectedNation)&&game.nations[selectedNation].human?button('Break Soviet–Japanese pact · +6 stress','dispatch',{type:'breakPact',nation:selectedNation},'danger full',game.phase===6||game.phase===7):''}<div class="spacer"></div><div class="eyebrow">Turn order</div><div class="flex">${game.turnOrder.map((n,i)=>`<span class="tag">${i+1} · ${NATIONS[n].short}</span>`).join('')}</div></div>`);}
function archive(){const slots=readStore().slots||[];return`<div class="layout wide"><div class="stack">${panel('Save & load','save',`<p>Autosaved after each decision on this browser. Export a file to carry the game between your phone and computer.</p><label class="field"><span>Checkpoint name</span><input id="save-name" placeholder="Before the offensive" maxlength="80"></label><div class="actionrow">${button('Save checkpoint','saveSlot',{},'primary')}${button('Export JSON','export',{},'teal')}${button('Import JSON','import',{},'small')}</div><div class="spacer"></div>${slots.map(x=>`<div class="orderrow"><span>◷</span><div>${escape(x.name)}<p>Round ${x.state.round} · ${SCENARIOS[x.state.scenario].name} · ${new Date(x.time).toLocaleString()}</p></div>${button('Load','loadSlot',{id:x.id},'small')}</div>`).join('')||'<div class="empty">No named checkpoints yet.</div>'}<div class="actionrow">${button('New game','newSetup',{},'small')}${button('Undo last decision','undo',{},'small',!undo.length)}</div>`)}${panel('Rules & guidance','start',`<div class="choices">${Object.entries(HELP).map(([key,[label]])=>button(label+' <span class="muted">?</span>','help',{key},'small')).join('')}</div>`)} </div><div class="stack">${diplomacyPanel()}${panel('Source & verification','fidelity',`<p>Unofficial playable alpha. The interface uses original vector pieces and map rendering. Rule and component references, corrections and known edge cases are documented with the source.</p><div class="footer-links"><a href="docs/SOURCES.md" target="_blank">Sources & fidelity notes</a><a href="https://github.com/Nathan-Culver/war-room" target="_blank" rel="noopener">GitHub repository</a><a href="https://nightingale-games.com/war-room" target="_blank" rel="noopener">Official game & rules</a></div>`)}${panel('Session controls','ai',`<p>Difficulty: ${game.difficulty}. AI opponents use public positions, their own resources and the same rules as human nations.</p><div class="actionrow">${button(paused?'Resume AI':'Pause AI',paused?'resume':'pause',{},'small')}</div><p class="status-note">Seed ${game.seed} · Save format v${game.version}<br>${game.updatedAt?'Last decision '+new Date(game.updatedAt).toLocaleString():''}</p>`)} </div></div>`;}
function logPanel(limit=20){return panel('Operations journal','start',game.log.slice(0,limit).map(e=>`<div class="log-entry ${e.kind}"><small>ROUND ${e.round} / ${PHASES[e.phase]||'FINAL'}</small>${escape(e.text)}</div>`).join(''));}
function render(){if(mapController){mapSnapshot=mapController.destroy();mapController=null;}if(!game){app.innerHTML=welcome();return;}if(!game.nations[selectedNation])selectedNation=game.turnOrder[0];let body='';if(view==='theater')body=`<div class="layout"><div class="stack">${mapPanel()}${regionPanel()}</div><div class="stack">${operations()}${logPanel(6)}</div></div>`;if(view==='orders')body=`<div class="layout"><div class="stack">${ordersPanel()}${panel('Commands / '+NATIONS[selectedNation].short,'commands',game.commands.filter(c=>c.nation===selectedNation).map(c=>commandCard(c)).join('')||'<div class="empty">No commands.</div>')}</div><div class="stack">${operations()}${diplomacyPanel()}</div></div>`;if(view==='operations')body=`<div class="layout wide"><div class="stack">${operations()}</div><div class="stack">${logPanel(25)}${diplomacyPanel()}</div></div>`;if(view==='intel')body=`<div class="layout wide"><div class="stack">${nationalPanel(selectedNation)}${diplomacyPanel()}</div><div class="stack">${panel('Territory ledger','economy',`<div class="table-scroll"><table class="ledger"><thead><tr><th>Territory</th><th>O / I / OSR</th><th>Industry</th></tr></thead><tbody>${Object.keys(game.regions).filter(id=>game.regions[id].owner===selectedNation).map(id=>`<tr><td><a href="#" data-action="region" data-payload="${payload({region:id})}">${escape(REGIONS[id].name)}</a>${embattled(game,id)?' ⚑':''}</td><td>${RESOURCES.map(k=>regionIncome(game,id)[k]||0).join(' / ')}</td><td>${capacity(game,id)||'—'}</td></tr>`).join('')}</tbody></table></div>`)}</div></div>`;if(view==='archive')body=archive();app.innerHTML=chrome(header()+body);updateRouteNote();attachMap();}
function toast(msg){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function persist(){try{autosave(game);}catch{toast('Browser storage is unavailable or full. Export your game to keep a backup.');}}
function doAction(a,{keepUndo=true}={}){try{const previous=game,next=dispatch(game,a);if(keepUndo){undo.push(previous);if(undo.length>30)undo.shift();}game=next;const d=decision(game);if(d.nation&&game.nations[d.nation]?.human&&['planning','production'].includes(d.kind))selectedNation=d.nation;persist();render();pumpAI();return true;}catch(e){toast(e.message);return false;}}
function pumpAI(){clearTimeout(autoTimer);if(!game||paused||game.winner)return;const d=decision(game);if(!d.nation||game.nations[d.nation]?.human){busy=false;return;}busy=true;autoTimer=setTimeout(()=>{try{let count=0;while(count++<35){const d=decision(game);if(!d.nation||game.nations[d.nation]?.human||game.winner){busy=false;break;}game=applyAI(game);}const next=decision(game);if(next.nation&&game.nations[next.nation]?.human&&['planning','production'].includes(next.kind))selectedNation=next.nation;persist();render();pumpAI();}catch(e){busy=false;paused=true;render();toast('AI paused: '+e.message+'. Your autosave is intact.');}},30);}
function showDialog(heading,body,footer=''){dialog.innerHTML=`<div class="dialoghead"><h2 id="dialog-title">${heading}</h2><button class="close" data-close aria-label="Close dialog">×</button></div><div class="dialogbody">${body}</div>${footer?`<div class="dialogfooter">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function showHelp(key){const[h,txt]=HELP[key]||HELP.start;showDialog(h,`<div class="helptext"><p>${txt}</p>${game?`<div class="infobox"><b>Current situation</b><br>${escape(guidance(game,decision(game))[0])}<br>${escape(guidance(game,decision(game))[1])}</div>`:''}<p style="margin-top:16px;font-size:10px">Use Escape or × to close. Official Second Edition rules are linked on the reference page.</p></div>`);}
function manageCommand(id){const c=game.commands.find(c=>c.id===id);if(!c)return;const allowed=canReorganize(game,c.nation,c.region);showDialog(category(c).toUpperCase()+' '+c.number,`${commandCard(c,false)}${allowed?`<div class="spacer"></div><h3>Split selected units into a new command ${help('commands')}</h3>${c.units.map(u=>`<label class="check"><input type="checkbox" name="split-unit" value="${u.uid}"><span>${UNITS[u.type].name} · ${u.uid}</span></label>`).join('')}${button('Split selected units','splitCommand',{command:c.id,nation:c.nation},'teal full')}<div class="spacer"></div><h3>Merge this command into</h3><div class="choices" style="margin-top:10px">${game.commands.filter(x=>x.id!==id&&x.nation===c.nation&&x.region===c.region&&category(x)===category(c)&&x.units.length+c.units.length<=8&&!x.carrierFighter&&!x.neutral).map(x=>button(category(x).toUpperCase()+' '+x.number+' · '+x.units.length+' units','mergeCommand',{from:id,into:x.id,nation:c.nation})).join('')||'<p style="font-size:11px">No compatible command with enough capacity.</p>'}</div>`:'<div class="infobox" style="margin-top:12px">Reorganization is not allowed in this step. Wait for Refit, or reorganize during Economy, Morale or Production.</div>'}`);}
function updateRouteNote(){if(!game)return;const command=document.querySelector('#order-command'),dest=document.querySelector('#order-destination'),note=document.querySelector('#order-route-note');if(!command||!dest||!note)return;const c=game.commands.find(c=>c.id===command.value),path=c?movementPath(game,c,dest.value):null;note.textContent=path?'Route now: '+path.map(displayId).join(' → ')+'. Rechecked during movement.':'No legal route in the current position. A later movement may change this.';}
function goodsDialog(n){const cost=productionCost(game.nations[n].plan);showDialog('Produce civilian goods',`<p class="helptext">Choose any five resources. Civilian goods arrive immediately and can be spent in later Morale phases.</p><div class="formgrid">${RESOURCES.map(k=>`<label class="field"><span>${k.toUpperCase()} (${game.nations[n].resources[k]-cost[k]} unreserved)</span><input id="goods-${k}" type="number" min="0" max="${game.nations[n].resources[k]-cost[k]}" value="0"></label>`).join('')}</div>`,button('Queue civilian goods','confirmGoods',{nation:n},'primary'));}
function tradeDialog(n){const neutrals=Object.keys(game.regions).filter(id=>tradeAccess(game,n,id));showDialog('Trade & infrastructure',`<p class="helptext">Each nation may trade once in Global War. Trade is declared before purchases are revealed.</p><div class="choices">${neutrals.flatMap(id=>RESOURCES.filter(k=>k!==REGIONS[id].trade).map(give=>button(REGIONS[id].name+': give '+({oil:2,iron:3,osr:5}[give])+' '+give+', gain '+({oil:2,iron:3,osr:5}[REGIONS[id].trade])+' '+REGIONS[id].trade,'trade',{nation:n,region:id,give}))).join('')||'<div class="empty">No neutral trade is available.</div>'}</div>${game.options.bombRepair?`<div class="spacer"></div><h3>Bomb repair · 9 iron</h3><div class="choices">${Object.keys(game.regions).filter(id=>game.regions[id].owner===n&&game.regions[id].bombs).map(id=>button('Remove one bomb in '+REGIONS[id].name,'bombRepair',{nation:n,region:id})).join('')||'<p>No bombed territory under your control.</p>'}</div>`:''}`);}
const value=id=>document.getElementById(id)?.value;
async function handle(action,data){switch(action){
case'view':view=data.view;render();window.scrollTo({top:0,behavior:'instant'});break;
case'nation':selectedNation=data.nation;render();break;
case'region':selectedRegion=data.region;view='theater';render();if(data.focus)mapController?.focusRegion(data.region);break;
case'mapDetails':showDialog(REGIONS[selectedRegion].name,regionPanel());break;
case'help':showHelp(data.key);break;
case'newSetup':showDialog('Start a new game?',`<p class="helptext">Your current game remains autosaved until you begin the new scenario. Export a backup or save a named checkpoint before replacing it.</p>`,button('Choose scenario','confirmNewSetup',{},'primary'));break;
case'confirmNewSetup':dialog.close();game=null;render();break;
case'newGame':{mapSnapshot=null;setupHumans=[...document.querySelectorAll('input[name=human]:checked')].map(e=>e.value);game=createGame({scenario:setupScenario,humans:setupHumans,difficulty:value('difficulty'),seed:value('seed'),options:Object.fromEntries([...document.querySelectorAll('input[name=option]:checked')].map(e=>[e.value,true]))});selectedNation=setupHumans.find(n=>game.nations[n])||game.turnOrder[0];selectedRegion=NATIONS[selectedNation].capital;view='theater';paused=false;undo=[];persist();render();window.scrollTo({top:0});break;}
case'addOrder':{const p=game.nations[selectedNation],command=value('order-command'),to=value('order-destination'),orders=p.orders.filter(o=>o.command!==command);orders.push({command,to});doAction({type:'orders',nation:selectedNation,orders,bid:+value('oil-bid')});break;}
case'removeOrder':{const p=game.nations[selectedNation];doAction({type:'orders',nation:selectedNation,orders:p.orders.filter((_,i)=>i!==data.index),bid:+value('oil-bid')});break;}
case'sealOrders':if(doAction({type:'orders',nation:data.nation,orders:game.nations[data.nation].orders,bid:+value('oil-bid')})){doAction({type:'seal',nation:data.nation});view='operations';render();}break;
case'dispatch':doAction(data);break;
case'executeMove':doAction({type:'move',via:value('movement-via'),leave:[...document.querySelectorAll('input[name=leave]:checked')].map(e=>e.value)});break;
case'launchFighter':doAction({type:'launch',to:value('launch-destination')});break;
case'capture':doAction({type:'capture',owner:value('capture-owner'),medals:Object.fromEntries([...document.querySelectorAll('[data-medals]')].map(e=>[e.dataset.medals,+e.value]))});break;
case'subEscape':doAction({type:'subEscape',to:value('sub-destination')});break;
case'landAir':doAction({type:'land',to:value('landing-destination')});break;
case'deployUnit':doAction({type:'deploy',to:value('deploy-destination')});break;
case'moraleSpend':doAction({type:'morale',count:+value('morale-count')});break;
case'convoyLiability':{const cs=REGIONS[data.region].convoys||[],choices=[];cs.forEach((cl,cluster)=>{for(const link of Object.keys(cl)){const ends=link.split('-');if(ends.length!==2||!ends.every(id=>game.regions[id]&&sideOf(game.regions[id].owner)==='axis'))continue;for(const owner of [...new Set(ends.map(id=>game.regions[id].owner))])if(ends.some(id=>game.nations[game.regions[id].owner]?.human))choices.push(button('Convoy '+(cluster+1)+' · liability to '+NATIONS[owner].short,'setConvoyOwner',{region:data.region,cluster,link,owner}));}});showDialog('Shared Axis convoy liability','<p class="helptext">When Axis nations control both endpoints, choose which controller bears losses.</p><div class="choices">'+(choices.join('')||'<div class="empty">No shared trans-ocean convoy is available to your alliance here.</div>')+'</div>');break;}
case'setConvoyOwner':if(doAction({type:'convoyOwner',...data}))dialog.close();break;
case'manage':manageCommand(data.command);break;
case'splitCommand':if(doAction({type:'split',nation:data.nation,command:data.command,units:[...dialog.querySelectorAll('input[name=split-unit]:checked')].map(e=>e.value)}))dialog.close();break;
case'mergeCommand':if(doAction({type:'merge',...data}))dialog.close();break;
case'buy':{const p=game.nations[data.nation];doAction({type:'plan',nation:data.nation,plan:[...p.plan,{type:data.type,region:value('production-factory')}]});break;}
case'removePurchase':doAction({type:'plan',nation:data.nation,plan:game.nations[data.nation].plan.filter((_,i)=>i!==data.index)});break;
case'goods':goodsDialog(data.nation);break;
case'confirmGoods':if(doAction({type:'plan',nation:data.nation,plan:[...game.nations[data.nation].plan,{type:'goods',payment:Object.fromEntries(RESOURCES.map(k=>[k,+value('goods-'+k)]))}]}))dialog.close();break;
case'tradeMenu':tradeDialog(data.nation);break;
case'trade':case'bombRepair':if(doAction({type:action,...data}))dialog.close();break;
case'pause':paused=true;busy=false;clearTimeout(autoTimer);render();toast('AI paused. Resume from Save & reference or the current operation.');break;
case'resume':paused=false;pumpAI();render();break;
case'saveSlot':try{saveSlot(value('save-name'),game);toast('Checkpoint saved on this device.');render();}catch{toast('Unable to save in this browser. Export a file instead.');}break;
case'loadSlot':game=structuredClone(loadSlot(data.id));undo=[];selectedNation=Object.keys(game.nations).find(n=>game.nations[n].human)||game.turnOrder[0];persist();render();pumpAI();toast('Checkpoint loaded.');break;
case'export':download(exportSave(game),`war-room-${game.scenario}-round-${game.round}.json`);toast('Save file exported to your browser downloads.');break;
case'import':document.querySelector('#import-file').click();break;
case'undo':if(undo.length){game=undo.pop();paused=true;busy=false;clearTimeout(autoTimer);persist();render();toast('Restored the previous decision. AI is paused.');}break;
}}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){dialog.close();return;}const h=e.target.closest('[data-help]');if(h){showHelp(h.dataset.help);return;}const region=e.target.closest('[data-region]');if(region){handle('region',{region:region.dataset.region});return;}const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{handle(el.dataset.action,JSON.parse(el.dataset.payload||'{}'));}catch(err){toast(err.message);}}});
document.addEventListener('change',e=>{if(e.target.name==='scenario'){setupHumans=[...document.querySelectorAll('input[name=human]:checked')].map(e=>e.value);setupScenario=e.target.value;if(!setupHumans.some(n=>SCENARIOS[setupScenario].nations.includes(n)))setupHumans=[SCENARIOS[setupScenario].nations[0]];render();}if(e.target.id==='find-region'&&e.target.value)handle('region',{region:e.target.value,focus:true});if(e.target.id==='order-command'){const c=game.commands.find(c=>c.id===e.target.value);const dest=document.querySelector('#order-destination');if(c&&dest)dest.value=c.region;updateRouteNote();}if(e.target.id==='order-destination')updateRouteNote();if(e.target.dataset.stance)doAction({type:'stance',uid:e.target.dataset.stance,stance:e.target.value});if(e.target.id==='battle-commander')doAction({type:'commander',commander:e.target.value});if(e.target.id==='movement-via'){const d=decision(game),c=game.commands.find(c=>c.id===d.order.command),plan=movementPlan(game,c,d.order.to,e.target.value||null);const container=document.querySelector('#pin-selection');if(container)container.innerHTML=plan.pin>0&&plan.pin<c.units.length?'<p style="font-size:11px;margin-top:12px">Leave '+plan.pin+' units pinned in '+displayId(plan.pinRegion)+':</p>'+c.units.map(u=>'<label class="check"><input type="checkbox" name="leave" value="'+u.uid+'"><span>'+UNITS[u.type].name+' '+u.uid+'</span></label>').join(''):'';}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.hasAttribute('data-region')){e.preventDefault();handle('region',{region:e.target.dataset.region});}});
document.querySelector('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const s=parseImport(await file.text());game=s;selectedNation=Object.keys(s.nations).find(n=>s.nations[n].human)||s.turnOrder[0];selectedRegion=NATIONS[selectedNation].capital;view='theater';undo=[];paused=false;persist();render();pumpAI();toast('Game loaded from '+file.name+'.');}catch(err){toast('Could not import: '+err.message);}e.target.value='';});
render();if(game)pumpAI();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
